sys_transform_script.script:
(function runTransformScript(source, map, log, target /*undefined onStart*/ ) {

    //Process Certificate first
    var certName = source.u_certification;
    var certType = source.u_certification_type;
    certType = certType.toString().toLowerCase();
    certType = certType.charAt(0).toUpperCase() + certType.slice(1);

    // Check if certificate already exists
    var certGR = new GlideRecord('x_kp101_kpmg_res_0_certificate');
    certGR.addQuery('name', certName);
    certGR.query();

    if (!certGR.next()) {
        // Create new certificate record
        var newCert = new GlideRecord('x_kp101_kpmg_res_0_certificate');
        newCert.initialize();
        newCert.name = certName;
        newCert.type = certType; // make sure field name is correct
        var points = 0;
        if (certType == "Micro" || certType == "Suite") {
            points = 50;
        } else if (certType == "Accreditation") {
            points = 100;
        }
        newCert.points = points;
        newCert.insert();
    }




    var userEmail = source.u_user_email;

    if (!userEmail || source.u_certification_status != "current") {
        ignore = true;
        return;
    }


    var certUserGR = new GlideRecord('x_kp101_kpmg_res_0_resource_profile');
    certUserGR.addQuery('resource_name.email', userEmail);
    certUserGR.query();

    // If no matching record → skip this row
    if (!certUserGR.hasNext()) {
        ignore = true;
    }
})(source, map, log, target);
